package in.sevasetu.amc.security;
import org.springframework.boot.ApplicationArguments;import org.springframework.boot.ApplicationRunner;import org.springframework.jdbc.core.simple.JdbcClient;import org.springframework.security.crypto.password.PasswordEncoder;import org.springframework.stereotype.Component;
@Component public class BootstrapPasswords implements ApplicationRunner{private final JdbcClient db;private final PasswordEncoder encoder;public BootstrapPasswords(JdbcClient db,PasswordEncoder encoder){this.db=db;this.encoder=encoder;}public void run(ApplicationArguments args){db.sql("select username,password_hash from amcservice.users where password_hash like '{bootstrap}%'").query((rs,n)->new String[]{rs.getString(1),rs.getString(2)}).list().forEach(r->db.sql("update amcservice.users set password_hash=:hash where username=:username and password_hash=:old").param("hash",encoder.encode(r[1].substring(11))).param("username",r[0]).param("old",r[1]).update());}}
